import {modal,toast,tone} from './core.js';
export const antennaOrder=['W','N','E'];
export const workshopCode=tide=>String(tide+137).padStart(3,'0');
export const pumpReady=s=>!!(s.tools&&s.seal&&s.valves?.join(',')==='true,false,true');
export function linkedRoom({state,persist,baseImage,image,baseName,name,message,spots}){
 const room=document.querySelector('.room-image'),baseMarkers=Array.from(room.children).filter(b=>b.className==='inspect'),label=room.querySelector('.room-label'),baseMessage=label?.textContent||'',extras=[];
 const nav=document.createElement('button');nav.id='area';nav.className='room-nav';document.querySelector('#controls').append(nav);document.querySelector('#controls').classList.add('resort-controls');
 function render(){const away=state.area===name;room.style.backgroundImage=`url(assets/${away?image:baseImage})`;for(const b of baseMarkers)b.style.display=away?'none':'';for(const b of extras)b.style.display=away?'':'none';nav.textContent=away?'← '+baseName:name+' →';if(label)label.textContent=away?message:baseMessage}
 for(const [title,x,y,action]of spots){const b=document.createElement('button');b.className='inspect';b.setAttribute('aria-label',title);b.textContent='+';b.style.left=`calc(${x}% - 22px)`;b.style.top=`calc(${y}% - 22px)`;b.onclick=action;room.append(b);extras.push(b)}nav.onclick=()=>{state.area=state.area===name?baseName:name;persist();render()};render();return {show(){state.area=name;persist();render()}};
}
function closeup(image,title,body,x,y,buttons){return modal(title,`<div class="room-detail" style="background-image:url(assets/${image});background-position:${x}% ${y}%"></div>${body}`,buttons)}
export function receptionLounge(state,persist){
 if(state.tuned){state.lead=true;state.antenna=true}state.lead??=false;state.antenna??=false;
 const detail=(title,body,x,y,buttons)=>closeup('resort-lounge.webp',title,body,x,y,buttons);
 function log(){detail('The keeper’s route', '<div class="paper-note">The storm route begins at the <strong>WEST pier</strong>, passes the <strong>NORTH light</strong>, then follows the <strong>EAST channel</strong>.<p>Three bearings. Read them in the order travelled. The keeper used them to lock his travel case.</p></div>',34,40)}
 function travelCase(){if(state.lead){detail('The opened travel case','<p>You took the spare antenna lead. Its brass connector fits the listening station on the far desk.</p>',54,68);return}let chosen=[];const d=detail('The keeper’s travel case','<p>Three compass bearings release the lock. The route log in this lounge gives their order.</p><div id="bearings" class="puzzle-row"></div><p id="bearing-readout">No bearings selected.</p>',54,68,[{text:'Open case',close:false,action:()=>{if(chosen.join('')===antennaOrder.join('')){state.lead=true;persist();d.remove();tone(650,.2);toast('Antenna lead collected · connect it at the listening station')}else d.querySelector('#bearing-readout').textContent='The lock holds. Follow the keeper’s route in order.'}},{text:'Clear',close:false,action:()=>{chosen=[];d.querySelector('#bearing-readout').textContent='No bearings selected.'}},{text:'Back'}]);for(const letter of ['N','E','S','W']){const b=document.createElement('button');b.textContent=letter;b.onclick=()=>{if(chosen.length===3)chosen=[];chosen.push(letter);d.querySelector('#bearing-readout').textContent=chosen.join(' → ')};d.querySelector('#bearings').append(b)}}
 function antenna(){detail('The listening station',state.antenna?'<p>The aerial now feeds the reception radio. Return to reception, restore its power and tune to the lighthouse.</p>':state.lead?'<p>The spare lead matches the loose connector. Connect it to feed the reception radio.</p>':'<p>The aerial lead is missing. The keeper carried spare communications parts in his locked travel case.</p>',85,45,state.lead&&!state.antenna?[{text:'Connect antenna',action:()=>{state.antenna=true;persist();toast('Aerial connected · the reception radio can receive a signal')}},{text:'Back'}]:undefined)}
 return linkedRoom({state,persist,baseImage:'resort.webp',image:'resort-lounge.webp',baseName:'Reception',name:'Reading lounge',message:'The keeper left a route through the silence.',spots:[['Route log',34,40,log],['Travel case',54,68,travelCase],['Listening station',85,45,antenna],['Lighthouse chart',89,20,()=>detail('The coastal broadcast','<div class="paper-note">NORTH HEAD LIGHTHOUSE<p>Emergency frequency: <strong>94.6 MHz</strong></p>The receiving radio is at reception.</div>',89,20)]]});
}
export function harborWorkshop(state,persist){
 state.workshop??={tools:false,seal:false,can:false,pump:false,fueled:!!state.complete,valves:[false,false,false]};const w=state.workshop;
 const detail=(title,body,x,y,buttons)=>closeup('harbor-workshop.webp',title,body,x,y,buttons);
 function manual(){detail('The pump service manual',`<div class="paper-note">TOOL CABINET<p>Take the tide gauge reading in centimetres and <strong>add 137</strong>. Use all three digits.</p>FUEL TRANSFER<p>Fit a fresh impeller seal. Set the valves:<br><strong>Intake OPEN · Bypass CLOSED · Return OPEN</strong>.</p><i>Prime the pump before filling the can.</i></div>`,10,59)}
 function cabinet(){if(w.tools){detail('The tool cabinet','<p>The service wrench is already in your satchel.</p>',41,32);return}const d=detail('The service cabinet','<p>The manual explains how the harbor tide becomes a cabinet code.</p><input id="servicecode" inputmode="numeric" maxlength="3" aria-label="Service cabinet code"><p id="servicefeedback"></p>',41,32,[{text:'Unlock',close:false,action:()=>{if(d.querySelector('#servicecode').value===workshopCode(state.tide)){w.tools=true;persist();d.remove();toast('Service wrench collected')}else d.querySelector('#servicefeedback').textContent='The lock holds. Add 137 to the tide gauge digits.'}},{text:'Back'}])}
 function pump(){const d=detail('The fuel transfer pump',w.pump?'<p>The pump is primed. Take the empty fuel can, then fill it here.</p>':'<p>Replace the impeller seal and set the three valves using the service manual.</p><div id="valves" class="puzzle-row"></div><p id="pumpfeedback"></p>',57,40,[{text:w.pump?'Fill fuel can':'Repair & prime',close:false,action:()=>{if(w.pump){if(!w.can){d.querySelector('.modal-body').innerHTML='<p>Collect the empty can beside the workbench first.</p>';return}w.fueled=true;persist();d.remove();toast('Fuel can filled · refuel the launch in the boathouse')}else if(pumpReady(w)){w.pump=true;persist();d.remove();tone(400,.3);pump()}else d.querySelector('#pumpfeedback').textContent=!w.tools?'The service wrench is locked in the tool cabinet.':!w.seal?'Collect the fresh seal from the parts tray.':'The valve pattern is wrong. Check the manual.'}},{text:'Back'}]);if(!w.pump)for(let i=0;i<3;i++){const b=document.createElement('button');const show=()=>b.textContent=['Intake','Bypass','Return'][i]+': '+(w.valves[i]?'OPEN':'CLOSED');show();b.onclick=()=>{w.valves[i]=!w.valves[i];show();persist()};d.querySelector('#valves').append(b)}}
 return linkedRoom({state,persist,baseImage:'boathouse.webp',image:'harbor-workshop.webp',baseName:'Boathouse',name:'Engine workshop',message:'The service launch needs more than a key.',spots:[['Service manual',10,59,manual],['Tool cabinet',41,32,cabinet],['Impeller seal',87,86,()=>{w.seal=true;persist();toast('Fresh impeller seal collected')}],['Fuel can',92,67,()=>{w.can=true;persist();toast(w.fueled?'The can is filled and ready.':'Empty fuel can collected')}],['Transfer pump',57,40,pump]]});
}
